keyframes:
@keyframes slide-up-and-fade { 
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes slide-right-and-fade { 
  0% { opacity: 0; transform: translateX(-4px); }
  100% { opacity: 1; transform: translateX(0px); }
}

@keyframes slide-down-and-fade { 
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes slide-left-and-fade { 
  0% { opacity: 0; transform: translateX(4px); }
  100% { opacity: 1; transform: translateX(0px); }
}

@keyframes _show-content_svmz2_1 { 
  0% { opacity: 0; transform: translateY(5%) scale(0.96); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}

@keyframes _scaleIn_12i4m_1 { 
  0% { opacity: 0; rotate: x -8deg; scale: 0.97; }
  100% { opacity: 1; rotate: x 0deg; scale: 1; }
}

@keyframes _scaleOut_12i4m_1 { 
  0% { opacity: 1; rotate: x 0deg; scale: 1; }
  100% { opacity: 0; rotate: x -8deg; scale: 0.97; }
}

@keyframes _slide-down-and-fade_1ll2y_1 { 
  0% { opacity: 0; transform: translateY(-2px); }
  100% { opacity: 1; transform: translateY(0px); }
}
